def laurent_coefficients(expression: sp.Expr, momentum: sp.Symbol,
                         transfer: sp.Symbol) -> dict[tuple[int, int], sp.Expr]:
    """Exact coefficients in z=exp(i*k), w=exp(i*q/2), after cancellation."""
    z, w = sp.symbols("z w", nonzero=True)
    expanded = sp.expand(expression.rewrite(sp.exp))
    substitutions = {}
    for exponential in expanded.atoms(sp.exp):
        phase = sp.expand(exponential.args[0] / I)
        a = sp.simplify(sp.diff(phase, momentum))
        b = sp.simplify(2 * sp.diff(phase, transfer))
        if not (a.is_Integer and b.is_Integer
                and sp.simplify(phase - a * momentum - b * transfer / 2) == 0):
            raise ValueError("symbol is not a finite Laurent polynomial on the declared half-grid")
        substitutions[exponential] = z**a * w**b
    polynomial = sp.expand(expanded.xreplace(substitutions))
    coefficients: dict[tuple[int, int], sp.Expr] = {}
    for term in sp.Add.make_args(polynomial):
        powers = term.as_powers_dict()
        a, b = powers.get(z, sp.Integer(0)), powers.get(w, sp.Integer(0))
        if not (a.is_Integer and b.is_Integer):
            raise ValueError("nonintegral Laurent exponent")
        coefficient = sp.simplify(term / (z**a * w**b))
        if coefficient.has(z, w, momentum, transfer):
            raise ValueError("uncollected non-Laurent coefficient")
        key = (int(a), int(b))
        coefficients[key] = sp.simplify(coefficients.get(key, 0) + coefficient)
    return {key: coefficient for key, coefficient in sorted(coefficients.items())
            if coefficient != 0}
